SELECT  FROM workflow
WHERE workspace_id = #{workspaceId}
ORDER BY updated_at DESC, id DESC

SELECT  FROM workflow
WHERE workspace_id = #{workspaceId} AND id = #{id}
FOR UPDATE

SELECT 
FROM rule r
WHERE r.workspace_id = #{workspaceId}
  AND NOT EXISTS (
    SELECT 1 FROM workflow w
    WHERE w.workspace_id = #{workspaceId}
      AND w.legacy_rule_id = r.id
  )
ORDER BY r.id

mapper.update:
UPDATE workflow
SET enabled = #{enabled}, updated_by_id = #{updatedById}
WHERE workspace_id = #{workspaceId} AND id = #{id}

UPDATE workflow
SET active_version_id = #{activeVersionId}, updated_by_id = #{updatedById}
WHERE workspace_id = #{workspaceId} AND id = #{id}
